#!/usr/bin/env python3
import csv
import os
import sys
from collections import defaultdict

# Areas to check
areas_to_check = [
    "Portland-Vancouver-Hillsboro, OR-WA",
    "Wichita, KS", 
    "San Diego-Carlsbad, CA"
]

# Years to check
years = list(range(2000, 2011))

# Threshold for Good CO AQI (ppm)
GOOD_THRESHOLD = 4.4

def analyze_year(year):
    """Analyze daily CO data for a given year."""
    daily_file_2010 = "/tmp/pinchbench/ded248a7/agent_workspace/epa_data/daily_42101_2010.csv"
    daily_file_2000 = "/tmp/pinchbench/1f1b3113/agent_workspace/daily_42101_2000.csv"

    if year == 2000:
        daily_file = daily_file_2000
    elif year == 2010:
        daily_file = daily_file_2010
    else:
        # No daily data for other years
        return None

    if not os.path.exists(daily_file):
        print(f"No daily data file for {year}")
        return None

    print(f"Analyzing {year}...")

    # Track for each area: for each day, track if all monitors reported Good values
    # Structure: area -> date -> {max_value, monitor_count}
    area_data = {area: defaultdict(lambda: {'max_value': 0, 'monitor_count': 0, 'all_good': True}) for area in areas_to_check}

    # Also track which monitors exist in each area
    area_monitors = {area: set() for area in areas_to_check}

    with open(daily_file, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            cbsa_name = row['CBSA Name']
            if cbsa_name in areas_to_check:
                date = row['Date Local']
                try:
                    # Get 1st Max Value (max concentration for the day)
                    max_value = float(row['1st Max Value'])
                except (ValueError, KeyError):
                    continue

                # Track monitor (by site identifier)
                site_id = f"{row['State Code']}-{row['County Code']}-{row['Site Num']}-{row['POC']}"
                area_monitors[cbsa_name].add(site_id)

                # Update for this date
                date_data = area_data[cbsa_name][date]
                date_data['monitor_count'] += 1
                if max_value > date_data['max_value']:
                    date_data['max_value'] = max_value
                if max_value > GOOD_THRESHOLD:
                    date_data['all_good'] = False

    # Now check if every day had all monitors reporting Good values
    results = {}
    for area in areas_to_check:
        dates = sorted(area_data[area].keys())
        if not dates:
            results[area] = {'all_days_good': False, 'reason': 'No data', 'num_days': 0, 'num_monitors': 0}
            continue

        all_good = True
        problematic_dates = []
        for date, data in area_data[area].items():
            if not data['all_good'] or data['monitor_count'] == 0:
                all_good = False
                problematic_dates.append((date, data['max_value'], data['monitor_count']))
                # Break early if we find a bad day
                if len(problematic_dates) > 5:
                    break

        results[area] = {
            'all_days_good': all_good,
            'num_days': len(dates),
            'num_monitors': len(area_monitors[area]),
            'problematic_dates': problematic_dates[:5] if not all_good else []
        }

    return results

def main():
    """Main analysis."""
    yearly_results = {}

    for year in years:
        results = analyze_year(year)
        if results is not None:
            yearly_results[year] = results

    # Print summary
    print("\n=== SUMMARY ===")
    for year in sorted(yearly_results.keys()):
        print(f"\n{year}:")
        results = yearly_results[year]
        all_areas_good = True
        for area in areas_to_check:
            area_result = results[area]
            status = "✓ ALL GOOD" if area_result['all_days_good'] else "✗ NOT ALL GOOD"
            print(f"  {area}: {status}")
            print(f"    Days with data: {area_result['num_days']}, Monitors: {area_result['num_monitors']}")
            if area_result['problematic_dates']:
                print(f"    Problematic days (first 5):")
                for date, max_val, count in area_result['problematic_dates']:
                    print(f"      {date}: max={max_val} ppm, monitors={count}")
            if not area_result['all_days_good']:
                all_areas_good = False

        if all_areas_good:
            print(f"\n  → {year}: ALL THREE AREAS HAD ALL DAYS GOOD!")

    # Find years where all three areas had all days good
    print("\n=== FINAL ANSWER ===")
    good_years = []
    for year in sorted(yearly_results.keys()):
        results = yearly_results[year]
        if all(results[area]['all_days_good'] for area in areas_to_check):
            good_years.append(str(year))

    if good_years:
        print(f"Years where all three areas had CO AQI ≤4.4 ppm for every day: {', '.join(good_years)}")
        # Write to answer.txt
        with open('answer.txt', 'w') as f:
            f.write(', '.join(good_years))
    else:
        print("No years found where all three areas had CO AQI ≤4.4 ppm for every day.")
        # Write empty or "none" to answer.txt
        with open('answer.txt', 'w') as f:
            f.write('')

if __name__ == '__main__':
    main()

